package dev.guardianai.sense;

import dev.guardianai.model.ThreatSeverity;

import java.util.Collections;
import java.util.List;

/**
 * Child-first explainable safety report generated by GuardianAi Sense.
 * Sent directly to the child with educational guidance rather than punitive alerts.
 */
public class ConversationRiskReport {
    private final SafetyCategory category;
    private final ThreatSeverity severity;
    private final List<String> detectedSignals;
    private final String childExplanation;
    private final List<String> safeOptionsForChild;
    private final boolean shouldPromptSos;

    public ConversationRiskReport(
            SafetyCategory category,
            ThreatSeverity severity,
            List<String> detectedSignals,
            String childExplanation,
            List<String> safeOptionsForChild,
            boolean shouldPromptSos) {
        this.category = category;
        this.severity = severity;
        this.detectedSignals = detectedSignals != null ? detectedSignals : Collections.emptyList();
        this.childExplanation = childExplanation;
        this.safeOptionsForChild = safeOptionsForChild != null ? safeOptionsForChild : Collections.emptyList();
        this.shouldPromptSos = shouldPromptSos;
    }

    public SafetyCategory getCategory() {
        return category;
    }

    public ThreatSeverity getSeverity() {
        return severity;
    }

    public List<String> getDetectedSignals() {
        return detectedSignals;
    }

    public String getChildExplanation() {
        return childExplanation;
    }

    public List<String> getSafeOptionsForChild() {
        return safeOptionsForChild;
    }

    public boolean shouldPromptSos() {
        return shouldPromptSos;
    }
}
